head.script:
scwin.screenId = "uldmgt50308";

///////// 1. 변수 및 선언 영역 /////////

scwin.frame = undefined;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return " " + String(dma_disclosureLaw.get("lawTitle")) + " (개정일 " + String((String(String(dma_disclosureLaw.get("lawAmendDd")) == null ? '' : String(dma_disclosureLaw.get("lawAmendDd"))) === '' ? '' : String("yyyy-MM-dd").replace(/yyyy/g, String(String(dma_disclosureLaw.get("lawAmendDd"))).slice(0,4)).replace(/MM/g, String(String(dma_disclosureLaw.get("lawAmendDd"))).slice(4,6)).replace(/dd/g, String(String(dma_disclosureLaw.get("lawAmendDd"))).slice(6,8)).replace(/HH/g, String(String(dma_disclosureLaw.get("lawAmendDd"))).slice(8,10)).replace(/mm/g, String(String(dma_disclosureLaw.get("lawAmendDd"))).slice(10,12)).replace(/ss/g, String(String(dma_disclosureLaw.get("lawAmendDd"))).slice(12,14)))) + ") "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.list();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50308.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50308.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.form_1_onsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.form_1_onsubmit = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin form_1_onsubmit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        return false
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50308.form_1_onsubmit' }); }
};

