///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_List_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_List_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr", unresolved: "action:self_submit:tx_fn_List_xhr" };
};

/**
 * @method
 * @name scwin.tx_fn_LawAll_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_LawAll_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_LawAll_xhr", unresolved: "action:self_submit:tx_fn_LawAll_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.list = async function () {
    /* sdd-asis-lifecycle:begin fn_List — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('indexTab').setSrc("/img/filing/body/tab_index_selected.gif");
    $c.util.getComponent('contentTab').setSrc("/img/filing/body/tab_content_unselected.gif");
    scwin.form_listForm.action = "/filing/onlineDisclosureLaw.do";
    $c.util.getComponent('dma_ListXhrReq').set('method', "findDisclosureLawItems");
    $c.util.getComponent('txt_lawListDiv').setValue(await scwin.tx_fn_List_xhr());
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.lawAll
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.lawAll = async function () {
    /* sdd-asis-lifecycle:begin fn_LawAll — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('indexTab').setSrc("/img/filing/body/tab_index_unselected.gif");
    $c.util.getComponent('contentTab').setSrc("/img/filing/body/tab_content_selected.gif");
    scwin.form_listForm.action = "/filing/onlineDisclosureLaw.do";
    $c.util.getComponent('dma_ListXhrReq').set('method', "findDisclosureLawAllItems");
    $c.util.getComponent('txt_lawListDiv').setValue(await scwin.tx_fn_LawAll_xhr());
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.lawContentDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param lawItmSeq
 * @returns
 * @hidden N
*/
scwin.lawContentDetail = async function (lawItmSeq) {
    /* sdd-asis-lifecycle:begin fn_LawContentDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/uldmgt50309/uldmgt50309.xml?method=findDisclosureLawItemContent" + "&lawNo=" + dma_disclosureLaw.get("lawNo") + "&lawItmSeq=" + lawItmSeq;
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "lawContentPop", popupName: "lawContentPop", width: "700", height: "650" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.addDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.addDetail = function () {
    /* sdd-asis-lifecycle:begin fn_AddDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/updateOnlineDisclosureLawDetail.do?method=findDisclosureLawArticles" + "&lawNo=" + $c.util.getComponent('dma_ListXhrReq').get('lawNo') + "&dtruleLawNo=" + $c.util.getComponent('dma_ListXhrReq').get('dtruleLawNo');
    goURL(_url);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.modLawItm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.modLawItm = function () {
    /* sdd-asis-lifecycle:begin modLawItm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/updateOnlineDisclosureLaw.do?method=prepareUpdateDisclosureLawItems" + "&lawNo=" + $c.util.getComponent('dma_ListXhrReq').get('lawNo') + "&mode=update";
    goURL(_url);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.lawAddrule
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.lawAddrule = async function () {
    /* sdd-asis-lifecycle:begin fn_LawAddrule — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/uldmgt50309/uldmgt50309.xml?method=findDisclosureLawAddruleContent" + "&lawNo=" + dma_disclosureLaw.get("lawNo") + "";
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "lawAddrulePop", popupName: "lawAddrulePop" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.lawList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.lawList = function () {
    /* sdd-asis-lifecycle:begin fn_LawList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    goURL("/filing/disclosureLaw.do");
    /* sdd-asis-lifecycle:end */
};
